code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    signatures = []
    for r, row in enumerate(grid):
        sig = tuple((c, v) for c, v in enumerate(row) if v)
        if len(sig) >= 2:
            signatures.append((r, sig))
    runs = []
    i = 0
    while i < len(signatures):
        j = i + 1
        while j < len(signatures) and signatures[j][0] == signatures[j-1][0] + 1 and signatures[j][1] == signatures[i][1]:
            j += 1
        if j-i >= 2:
            runs.append((j-i, signatures[i][0], signatures[i][1]))
        i = j
    if not runs:
        return [row[:] for row in grid]
    _, stripe_top, sig = max(runs)
    colors = [v for _, v in sig]
    stripe_rows = set(range(stripe_top, stripe_top + max(n for n, r, s in runs if r == stripe_top and s == sig)))
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in seen and r not in stripe_rows:
                color = grid[r][c]
                q = [(r,c)]; seen.add((r,c)); cells=[]
                while q:
                    y,x=q.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color and ny not in stripe_rows:
                            seen.add((ny,nx)); q.append((ny,nx))
                if color in colors:
                    comps.append((len(cells), color, cells))
    if not comps:
        return [row[:] for row in grid]
    _, base_color, cells = max(comps, key=lambda x:x[0])
    top=min(y for y,x in cells); left=min(x for y,x in cells)
    bottom=max(y for y,x in cells); right=max(x for y,x in cells)
    mask={(y-top,x-left) for y,x in cells}
    layer_h=bottom-top+1; layer_w=right-left+1
    index=colors.index(base_color)
    start=top-index*layer_h
    out=[[0]*w for _ in range(h)]
    for i,color in enumerate(colors):
        for dy,dx in mask:
            y=start+i*layer_h+dy; x=left+dx
            if 0<=y<h and 0<=x<w:
                out[y][x]=color
    return out
'''
